// Generated from NIST OSCAL content. Do not edit by hand.
export const FAMILY_PS: NistCatalogFamily = {"code":"PS","name":"Personnel Security","controls":[{"id":"PS-1","oscal_id":"ps-1","family":"PS","title":"Policy and Procedures","statement":"a. Develop, document, and disseminate to <organization-defined personnel or roles>:\n  Develop, document, and disseminate to <organization-defined personnel or roles>:\n  1. <organization-defined parameter> personnel security policy that:\n    <organization-defined parameter> personnel security policy that:\n    (a) Addresses purpose, scope, roles, responsibilities, management commitment, coordination among organizational entities, and compliance; and\n    (b) Is consistent with applicable laws, executive orders, directives, regulations, policies, standards, and guidelines; and\n  2. Procedures to facilitate the implementation of the personnel security policy and the associated personnel security controls;\nb. Designate an <official> to manage the development, documentation, and dissemination of the personnel security policy and procedures; and\nc. Review and update the current personnel security:\n  Review and update the current personnel security:\n  1. Policy <frequency> and following <events> ; and\n  2. Procedures <frequency> and following <events>.","supplemental_guidance":"Personnel security policy and procedures for the controls in the PS family that are implemented within systems and organizations. The risk management strategy is an important factor in establishing such policies and procedures. Policies and procedures contribute to security and privacy assurance. Therefore, it is important that security and privacy programs collaborate on their development. Security and privacy program policies and procedures at the organization level are preferable, in general, and may obviate the need for mission level or system-specific policies and procedures. The policy can be included as part of the general security and privacy policy or be represented by multiple policies reflecting the complex nature of organizations. Procedures can be established for security and privacy programs, for mission/business processes, and for systems, if needed. Procedures describe how the policies or controls are implemented and can be directed at the individual or role that is the object of the procedure. Procedures can be documented in system security and privacy plans or in one or more separate documents. Events that may precipitate an update to personnel security policy and procedures include, but are not limited to, assessment or audit findings, security incidents or breaches, or changes in applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Simply restating controls does not constitute an organizational policy or procedure.","implementation_level":"organization","parameters":[{"id":"ps-1_prm_1","label":"organization-defined personnel or roles"},{"id":"ps-01_odp.01","label":"personnel or roles"},{"id":"ps-01_odp.02","label":"personnel or roles"},{"id":"ps-01_odp.03","label":"","choices":["organization-level","mission/business process-level","system-level"],"how_many":"one-or-more"},{"id":"ps-01_odp.04","label":"official"},{"id":"ps-01_odp.05","label":"frequency"},{"id":"ps-01_odp.06","label":"events"},{"id":"ps-01_odp.07","label":"frequency"},{"id":"ps-01_odp.08","label":"events"}],"objectives":[{"id":"ps-1_obj.a-1","label":"PS-01a.[01]","text":"a personnel security policy is developed and documented;"},{"id":"ps-1_obj.a-2","label":"PS-01a.[02]","text":"the personnel security policy is disseminated to {{ insert: param, ps-01_odp.01 }};"},{"id":"ps-1_obj.a-3","label":"PS-01a.[03]","text":"personnel security procedures to facilitate the implementation of the personnel security policy and associated personnel security controls are developed and documented;"},{"id":"ps-1_obj.a-4","label":"PS-01a.[04]","text":"the personnel security procedures are disseminated to {{ insert: param, ps-01_odp.02 }};"},{"id":"ps-1_obj.a.1.a-1","label":"PS-01a.01(a)[01]","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy addresses purpose;"},{"id":"ps-1_obj.a.1.a-2","label":"PS-01a.01(a)[02]","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy addresses scope;"},{"id":"ps-1_obj.a.1.a-3","label":"PS-01a.01(a)[03]","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy addresses roles;"},{"id":"ps-1_obj.a.1.a-4","label":"PS-01a.01(a)[04]","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy addresses responsibilities;"},{"id":"ps-1_obj.a.1.a-5","label":"PS-01a.01(a)[05]","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy addresses management commitment;"},{"id":"ps-1_obj.a.1.a-6","label":"PS-01a.01(a)[06]","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy addresses coordination among organizational entities;"},{"id":"ps-1_obj.a.1.a-7","label":"PS-01a.01(a)[07]","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy addresses compliance;"},{"id":"ps-1_obj.a.1.b","label":"PS-01a.01(b)","text":"the {{ insert: param, ps-01_odp.03 }} personnel security policy is consistent with applicable laws, Executive Orders, directives, regulations, policies, standards, and guidelines;"},{"id":"ps-1_obj.b","label":"PS-01b.","text":"the {{ insert: param, ps-01_odp.04 }} is designated to manage the development, documentation, and dissemination of the personnel security policy and procedures;"},{"id":"ps-1_obj.c.1-1","label":"PS-01c.01[01]","text":"the current personnel security policy is reviewed and updated {{ insert: param, ps-01_odp.05 }};"},{"id":"ps-1_obj.c.1-2","label":"PS-01c.01[02]","text":"the current personnel security policy is reviewed and updated following {{ insert: param, ps-01_odp.06 }};"},{"id":"ps-1_obj.c.2-1","label":"PS-01c.02[01]","text":"the current personnel security procedures are reviewed and updated {{ insert: param, ps-01_odp.07 }};"},{"id":"ps-1_obj.c.2-2","label":"PS-01c.02[02]","text":"the current personnel security procedures are reviewed and updated following {{ insert: param, ps-01_odp.08 }}."}],"methods":[{"method":"examine","label":"PS-01-Examine"},{"method":"interview","label":"PS-01-Interview"}],"references":[{"title":"SP 800-12"},{"title":"SP 800-30"},{"title":"SP 800-39"},{"title":"SP 800-100"}],"related_controls":["PM-9","PS-8","SI-12"]},{"id":"PS-2","oscal_id":"ps-2","family":"PS","title":"Position Risk Designation","statement":"a. Assign a risk designation to all organizational positions;\nb. Establish screening criteria for individuals filling those positions; and\nc. Review and update position risk designations <frequency>.","supplemental_guidance":"Position risk designations reflect Office of Personnel Management (OPM) policy and guidance. Proper position designation is the foundation of an effective and consistent suitability and personnel security program. The Position Designation System (PDS) assesses the duties and responsibilities of a position to determine the degree of potential damage to the efficiency or integrity of the service due to misconduct of an incumbent of a position and establishes the risk level of that position. The PDS assessment also determines if the duties and responsibilities of the position present the potential for position incumbents to bring about a material adverse effect on national security and the degree of that potential effect, which establishes the sensitivity level of a position. The results of the assessment determine what level of investigation is conducted for a position. Risk designations can guide and inform the types of authorizations that individuals receive when accessing organizational information and information systems. Position screening criteria include explicit information security role appointment requirements. Parts 1400 and 731 of Title 5, Code of Federal Regulations, establish the requirements for organizations to evaluate relevant covered positions for a position sensitivity and position risk designation commensurate with the duties and responsibilities of those positions.","implementation_level":"organization","parameters":[{"id":"ps-02_odp","label":"frequency"}],"objectives":[{"id":"ps-2_obj.a","label":"PS-02a.","text":"a risk designation is assigned to all organizational positions;"},{"id":"ps-2_obj.b","label":"PS-02b.","text":"screening criteria are established for individuals filling organizational positions;"},{"id":"ps-2_obj.c","label":"PS-02c.","text":"position risk designations are reviewed and updated {{ insert: param, ps-02_odp }}."}],"methods":[{"method":"examine","label":"PS-02-Examine"},{"method":"interview","label":"PS-02-Interview"},{"method":"test","label":"PS-02-Test"}],"references":[{"title":"5 CFR 731"},{"title":"SP 800-181"}],"related_controls":["AC-5","AT-3","PE-2","PE-3","PL-2","PS-3","PS-6","SA-5","SA-21","SI-12"]},{"id":"PS-3","oscal_id":"ps-3","family":"PS","title":"Personnel Screening","statement":"a. Screen individuals prior to authorizing access to the system; and\nb. Rescreen individuals in accordance with <organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening>.","supplemental_guidance":"Personnel screening and rescreening activities reflect applicable laws, executive orders, directives, regulations, policies, standards, guidelines, and specific criteria established for the risk designations of assigned positions. Examples of personnel screening include background investigations and agency checks. Organizations may define different rescreening conditions and frequencies for personnel accessing systems based on types of information processed, stored, or transmitted by the systems.","implementation_level":"organization","parameters":[{"id":"ps-3_prm_1","label":"organization-defined conditions requiring rescreening and, where rescreening is so indicated, the frequency of rescreening"},{"id":"ps-03_odp.01","label":"conditions requiring rescreening"},{"id":"ps-03_odp.02","label":"frequency"}],"objectives":[{"id":"ps-3_obj.a","label":"PS-03a.","text":"individuals are screened prior to authorizing access to the system;"},{"id":"ps-3_obj.b-1","label":"PS-03b.[01]","text":"individuals are rescreened in accordance with {{ insert: param, ps-03_odp.01 }};"},{"id":"ps-3_obj.b-2","label":"PS-03b.[02]","text":"where rescreening is so indicated, individuals are rescreened {{ insert: param, ps-03_odp.02 }}."}],"methods":[{"method":"examine","label":"PS-03-Examine"},{"method":"interview","label":"PS-03-Interview"},{"method":"test","label":"PS-03-Test"}],"references":[{"title":"EO 13526"},{"title":"EO 13587"},{"title":"FIPS 199"},{"title":"FIPS 201-2"},{"title":"SP 800-60-1"},{"title":"SP 800-60-2"},{"title":"SP 800-73-4"},{"title":"SP 800-76-2"},{"title":"SP 800-78-4"}],"related_controls":["AC-2","IA-4","MA-5","PE-2","PM-12","PS-2","PS-6","PS-7","SA-21"],"enhancements":[{"id":"PS-3(1)","oscal_id":"ps-3.1","family":"PS","title":"Classified Information","statement":"Verify that individuals accessing a system processing, storing, or transmitting classified information are cleared and indoctrinated to the highest classification level of the information to which they have access on the system.","supplemental_guidance":"Classified information is the most sensitive information that the Federal Government processes, stores, or transmits. It is imperative that individuals have the requisite security clearances and system access authorizations prior to gaining access to such information. Access authorizations are enforced by system access controls (see [AC-3](#ac-3) ) and flow controls (see [AC-4](#ac-4)).","implementation_level":"organization","objectives":[{"id":"ps-3.1_obj-1","label":"PS-03(01)[01]","text":"individuals accessing a system processing, storing, or transmitting classified information are cleared;"},{"id":"ps-3.1_obj-2","label":"PS-03(01)[02]","text":"individuals accessing a system processing, storing, or transmitting classified information are indoctrinated to the highest classification level of the information to which they have access on the system."}],"methods":[{"method":"examine","label":"PS-03(01)-Examine"},{"method":"interview","label":"PS-03(01)-Interview"},{"method":"test","label":"PS-03(01)-Test"}],"related_controls":["AC-3","AC-4"],"is_enhancement":true,"parent_id":"PS-3"},{"id":"PS-3(2)","oscal_id":"ps-3.2","family":"PS","title":"Formal Indoctrination","statement":"Verify that individuals accessing a system processing, storing, or transmitting types of classified information that require formal indoctrination, are formally indoctrinated for all the relevant types of information to which they have access on the system.","supplemental_guidance":"Types of classified information that require formal indoctrination include Special Access Program (SAP), Restricted Data (RD), and Sensitive Compartmented Information (SCI).","implementation_level":"organization","methods":[{"method":"examine","label":"PS-03(02)-Examine"},{"method":"interview","label":"PS-03(02)-Interview"},{"method":"test","label":"PS-03(02)-Test"}],"related_controls":["AC-3","AC-4"],"is_enhancement":true,"parent_id":"PS-3"},{"id":"PS-3(3)","oscal_id":"ps-3.3","family":"PS","title":"Information Requiring Special Protective Measures","statement":"Verify that individuals accessing a system processing, storing, or transmitting information requiring special protection:\n(a) Have valid access authorizations that are demonstrated by assigned official government duties; and\n(b) Satisfy <additional personnel screening criteria>.","supplemental_guidance":"Organizational information that requires special protection includes controlled unclassified information. Personnel security criteria include position sensitivity background screening requirements.","implementation_level":"organization","parameters":[{"id":"ps-03.03_odp","label":"additional personnel screening criteria"}],"objectives":[{"id":"ps-3.3_obj.a","label":"PS-03(03)(a)","text":"individuals accessing a system processing, storing, or transmitting information requiring special protection have valid access authorizations that are demonstrated by assigned official government duties;"},{"id":"ps-3.3_obj.b","label":"PS-03(03)(b)","text":"individuals accessing a system processing, storing, or transmitting information requiring special protection satisfy {{ insert: param, ps-03.03_odp }}."}],"methods":[{"method":"examine","label":"PS-03(03)-Examine"},{"method":"interview","label":"PS-03(03)-Interview"},{"method":"test","label":"PS-03(03)-Test"}],"is_enhancement":true,"parent_id":"PS-3"},{"id":"PS-3(4)","oscal_id":"ps-3.4","family":"PS","title":"Citizenship Requirements","statement":"Verify that individuals accessing a system processing, storing, or transmitting <information types> meet <citizenship requirements>.","supplemental_guidance":"None.","implementation_level":"organization","parameters":[{"id":"ps-03.04_odp.01","label":"information types"},{"id":"ps-03.04_odp.02","label":"citizenship requirements"}],"methods":[{"method":"examine","label":"PS-03(04)-Examine"},{"method":"interview","label":"PS-03(04)-Interview"},{"method":"test","label":"PS-03(04)-Test"}],"is_enhancement":true,"parent_id":"PS-3"}]},{"id":"PS-4","oscal_id":"ps-4","family":"PS","title":"Personnel Termination","statement":"Upon termination of individual employment:\na. Disable system access within <time period>;\nb. Terminate or revoke any authenticators and credentials associated with the individual;\nc. Conduct exit interviews that include a discussion of <information security topics>;\nd. Retrieve all security-related organizational system-related property; and\ne. Retain access to organizational information and systems formerly controlled by terminated individual.","supplemental_guidance":"System property includes hardware authentication tokens, system administration technical manuals, keys, identification cards, and building passes. Exit interviews ensure that terminated individuals understand the security constraints imposed by being former employees and that proper accountability is achieved for system-related property. Security topics at exit interviews include reminding individuals of nondisclosure agreements and potential limitations on future employment. Exit interviews may not always be possible for some individuals, including in cases related to the unavailability of supervisors, illnesses, or job abandonment. Exit interviews are important for individuals with security clearances. The timely execution of termination actions is essential for individuals who have been terminated for cause. In certain situations, organizations consider disabling the system accounts of individuals who are being terminated prior to the individuals being notified.","implementation_level":"organization","parameters":[{"id":"ps-04_odp.01","label":"time period"},{"id":"ps-04_odp.02","label":"information security topics"}],"objectives":[{"id":"ps-4_obj.a","label":"PS-04a.","text":"upon termination of individual employment, system access is disabled within {{ insert: param, ps-04_odp.01 }};"},{"id":"ps-4_obj.b","label":"PS-04b.","text":"upon termination of individual employment, any authenticators and credentials are terminated or revoked;"},{"id":"ps-4_obj.c","label":"PS-04c.","text":"upon termination of individual employment, exit interviews that include a discussion of {{ insert: param, ps-04_odp.02 }} are conducted;"},{"id":"ps-4_obj.d","label":"PS-04d.","text":"upon termination of individual employment, all security-related organizational system-related property is retrieved;"},{"id":"ps-4_obj.e","label":"PS-04e.","text":"upon termination of individual employment, access to organizational information and systems formerly controlled by the terminated individual are retained."}],"methods":[{"method":"examine","label":"PS-04-Examine"},{"method":"interview","label":"PS-04-Interview"},{"method":"test","label":"PS-04-Test"}],"related_controls":["AC-2","IA-4","PE-2","PM-12","PS-6","PS-7"],"enhancements":[{"id":"PS-4(1)","oscal_id":"ps-4.1","family":"PS","title":"Post-employment Requirements","statement":"(a) Notify terminated individuals of applicable, legally binding post-employment requirements for the protection of organizational information; and\n(b) Require terminated individuals to sign an acknowledgment of post-employment requirements as part of the organizational termination process.","supplemental_guidance":"Organizations consult with the Office of the General Counsel regarding matters of post-employment requirements on terminated individuals.","implementation_level":"organization","objectives":[{"id":"ps-4.1_obj.a","label":"PS-04(01)(a)","text":"terminated individuals are notified of applicable, legally binding post-employment requirements for the protection of organizational information;"},{"id":"ps-4.1_obj.b","label":"PS-04(01)(b)","text":"terminated individuals are required to sign an acknowledgement of post-employment requirements as part of the organizational termination process."}],"methods":[{"method":"examine","label":"PS-04(01)-Examine"},{"method":"interview","label":"PS-04(01)-Interview"},{"method":"test","label":"PS-04(01)-Test"}],"is_enhancement":true,"parent_id":"PS-4"},{"id":"PS-4(2)","oscal_id":"ps-4.2","family":"PS","title":"Automated Actions","statement":"Use <automated mechanisms> to <organization-defined parameter>.","supplemental_guidance":"In organizations with many employees, not all personnel who need to know about termination actions receive the appropriate notifications, or if such notifications are received, they may not occur in a timely manner. Automated mechanisms can be used to send automatic alerts or notifications to organizational personnel or roles when individuals are terminated. Such automatic alerts or notifications can be conveyed in a variety of ways, including via telephone, electronic mail, text message, or websites. Automated mechanisms can also be employed to quickly and thoroughly disable access to system resources after an employee is terminated.","implementation_level":"organization","parameters":[{"id":"ps-04.02_odp.01","label":"automated mechanisms"},{"id":"ps-04.02_odp.02","label":"","choices":["notify {{ insert: param, ps-04.02_odp.03 }} of individual termination actions","disable access to system resources"],"how_many":"one-or-more"},{"id":"ps-04.02_odp.03","label":"personnel or roles"}],"methods":[{"method":"examine","label":"PS-04(02)-Examine"},{"method":"interview","label":"PS-04(02)-Interview"},{"method":"test","label":"PS-04(02)-Test"}],"is_enhancement":true,"parent_id":"PS-4"}]},{"id":"PS-5","oscal_id":"ps-5","family":"PS","title":"Personnel Transfer","statement":"a. Review and confirm ongoing operational need for current logical and physical access authorizations to systems and facilities when individuals are reassigned or transferred to other positions within the organization;\nb. Initiate <transfer or reassignment actions> within <time period following the formal transfer action>;\nc. Modify access authorization as needed to correspond with any changes in operational need due to reassignment or transfer; and\nd. Notify <personnel or roles> within <time period>.","supplemental_guidance":"Personnel transfer applies when reassignments or transfers of individuals are permanent or of such extended duration as to make the actions warranted. Organizations define actions appropriate for the types of reassignments or transfers, whether permanent or extended. Actions that may be required for personnel transfers or reassignments to other positions within organizations include returning old and issuing new keys, identification cards, and building passes; closing system accounts and establishing new accounts; changing system access authorizations (i.e., privileges); and providing for access to official records to which individuals had access at previous work locations and in previous system accounts.","implementation_level":"organization","parameters":[{"id":"ps-05_odp.01","label":"transfer or reassignment actions"},{"id":"ps-05_odp.02","label":"time period following the formal transfer action"},{"id":"ps-05_odp.03","label":"personnel or roles"},{"id":"ps-05_odp.04","label":"time period"}],"objectives":[{"id":"ps-5_obj.a","label":"PS-05a.","text":"the ongoing operational need for current logical and physical access authorizations to systems and facilities are reviewed and confirmed when individuals are reassigned or transferred to other positions within the organization;"},{"id":"ps-5_obj.b","label":"PS-05b.","text":"{{ insert: param, ps-05_odp.01 }} are initiated within {{ insert: param, ps-05_odp.02 }};"},{"id":"ps-5_obj.c","label":"PS-05c.","text":"access authorization is modified as needed to correspond with any changes in operational need due to reassignment or transfer;"},{"id":"ps-5_obj.d","label":"PS-05d.","text":"{{ insert: param, ps-05_odp.03 }} are notified within {{ insert: param, ps-05_odp.04 }}."}],"methods":[{"method":"examine","label":"PS-05-Examine"},{"method":"interview","label":"PS-05-Interview"},{"method":"test","label":"PS-05-Test"}],"related_controls":["AC-2","IA-4","PE-2","PM-12","PS-4","PS-7"]},{"id":"PS-6","oscal_id":"ps-6","family":"PS","title":"Access Agreements","statement":"a. Develop and document access agreements for organizational systems;\nb. Review and update the access agreements <frequency> ; and\nc. Verify that individuals requiring access to organizational information and systems:\n  Verify that individuals requiring access to organizational information and systems:\n  1. Sign appropriate access agreements prior to being granted access; and\n  2. Re-sign access agreements to maintain access to organizational systems when access agreements have been updated or <frequency>.","supplemental_guidance":"Access agreements include nondisclosure agreements, acceptable use agreements, rules of behavior, and conflict-of-interest agreements. Signed access agreements include an acknowledgement that individuals have read, understand, and agree to abide by the constraints associated with organizational systems to which access is authorized. Organizations can use electronic signatures to acknowledge access agreements unless specifically prohibited by organizational policy.","implementation_level":"organization","parameters":[{"id":"ps-06_odp.01","label":"frequency"},{"id":"ps-06_odp.02","label":"frequency"}],"objectives":[{"id":"ps-6_obj.a","label":"PS-06a.","text":"access agreements are developed and documented for organizational systems;"},{"id":"ps-6_obj.b","label":"PS-06b.","text":"the access agreements are reviewed and updated {{ insert: param, ps-06_odp.01 }};"},{"id":"ps-6_obj.c.1","label":"PS-06c.01","text":"individuals requiring access to organizational information and systems sign appropriate access agreements prior to being granted access;"},{"id":"ps-6_obj.c.2","label":"PS-06c.02","text":"individuals requiring access to organizational information and systems re-sign access agreements to maintain access to organizational systems when access agreements have been updated or {{ insert: param, ps-06_odp.02 }}."}],"methods":[{"method":"examine","label":"PS-06-Examine"},{"method":"interview","label":"PS-06-Interview"},{"method":"test","label":"PS-06-Test"}],"related_controls":["AC-17","PE-2","PL-4","PS-2","PS-3","PS-7","PS-8","SA-21","SI-12"],"enhancements":[{"id":"PS-6(1)","oscal_id":"ps-6.1","family":"PS","title":"Information Requiring Special Protection","statement":"","is_enhancement":true,"parent_id":"PS-6"},{"id":"PS-6(2)","oscal_id":"ps-6.2","family":"PS","title":"Classified Information Requiring Special Protection","statement":"Verify that access to classified information requiring special protection is granted only to individuals who:\n(a) Have a valid access authorization that is demonstrated by assigned official government duties;\n(b) Satisfy associated personnel security criteria; and\n(c) Have read, understood, and signed a nondisclosure agreement.","supplemental_guidance":"Classified information that requires special protection includes collateral information, Special Access Program (SAP) information, and Sensitive Compartmented Information (SCI). Personnel security criteria reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines.","implementation_level":"organization","objectives":[{"id":"ps-6.2_obj.a","label":"PS-06(02)(a)","text":"access to classified information requiring special protection is granted only to individuals who have a valid access authorization that is demonstrated by assigned official government duties;"},{"id":"ps-6.2_obj.b","label":"PS-06(02)(b)","text":"access to classified information requiring special protection is granted only to individuals who satisfy associated personnel security criteria;"},{"id":"ps-6.2_obj.c","label":"PS-06(02)(c)","text":"access to classified information requiring special protection is granted only to individuals who have read, understood, and signed a non-disclosure agreement."}],"methods":[{"method":"examine","label":"PS-06(02)-Examine"},{"method":"interview","label":"PS-06(02)-Interview"},{"method":"test","label":"PS-06(02)-Test"}],"is_enhancement":true,"parent_id":"PS-6"},{"id":"PS-6(3)","oscal_id":"ps-6.3","family":"PS","title":"Post-employment Requirements","statement":"(a) Notify individuals of applicable, legally binding post-employment requirements for protection of organizational information; and\n(b) Require individuals to sign an acknowledgment of these requirements, if applicable, as part of granting initial access to covered information.","supplemental_guidance":"Organizations consult with the Office of the General Counsel regarding matters of post-employment requirements on terminated individuals.","implementation_level":"organization","objectives":[{"id":"ps-6.3_obj.a","label":"PS-06(03)(a)","text":"individuals are notified of applicable, legally binding post-employment requirements for the protection of organizational information;"},{"id":"ps-6.3_obj.b","label":"PS-06(03)(b)","text":"individuals are required to sign an acknowledgement of applicable, legally binding post-employment requirements as part of being granted initial access to covered information."}],"methods":[{"method":"examine","label":"PS-06(03)-Examine"},{"method":"interview","label":"PS-06(03)-Interview"},{"method":"test","label":"PS-06(03)-Test"}],"related_controls":["PS-4"],"is_enhancement":true,"parent_id":"PS-6"}]},{"id":"PS-7","oscal_id":"ps-7","family":"PS","title":"External Personnel Security","statement":"a. Establish personnel security requirements, including security roles and responsibilities for external providers;\nb. Require external providers to comply with personnel security policies and procedures established by the organization;\nc. Document personnel security requirements;\nd. Require external providers to notify <personnel or roles> of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges, or who have system privileges within <time period> ; and\ne. Monitor provider compliance with personnel security requirements.","supplemental_guidance":"External provider refers to organizations other than the organization operating or acquiring the system. External providers include service bureaus, contractors, and other organizations that provide system development, information technology services, testing or assessment services, outsourced applications, and network/security management. Organizations explicitly include personnel security requirements in acquisition-related documents. External providers may have personnel working at organizational facilities with credentials, badges, or system privileges issued by organizations. Notifications of external personnel changes ensure the appropriate termination of privileges and credentials. Organizations define the transfers and terminations deemed reportable by security-related characteristics that include functions, roles, and the nature of credentials or privileges associated with transferred or terminated individuals.","implementation_level":"organization","parameters":[{"id":"ps-07_odp.01","label":"personnel or roles"},{"id":"ps-07_odp.02","label":"time period"}],"objectives":[{"id":"ps-7_obj.a","label":"PS-07a.","text":"personnel security requirements are established, including security roles and responsibilities for external providers;"},{"id":"ps-7_obj.b","label":"PS-07b.","text":"external providers are required to comply with personnel security policies and procedures established by the organization;"},{"id":"ps-7_obj.c","label":"PS-07c.","text":"personnel security requirements are documented;"},{"id":"ps-7_obj.d","label":"PS-07d.","text":"external providers are required to notify {{ insert: param, ps-07_odp.01 }} of any personnel transfers or terminations of external personnel who possess organizational credentials and/or badges or who have system privileges within {{ insert: param, ps-07_odp.02 }};"},{"id":"ps-7_obj.e","label":"PS-07e.","text":"provider compliance with personnel security requirements is monitored."}],"methods":[{"method":"examine","label":"PS-07-Examine"},{"method":"interview","label":"PS-07-Interview"},{"method":"test","label":"PS-07-Test"}],"references":[{"title":"SP 800-35"},{"title":"SP 800-63-3"}],"related_controls":["AT-2","AT-3","MA-5","PE-3","PS-2","PS-3","PS-4","PS-5","PS-6","SA-5","SA-9","SA-21"]},{"id":"PS-8","oscal_id":"ps-8","family":"PS","title":"Personnel Sanctions","statement":"a. Employ a formal sanctions process for individuals failing to comply with established information security and privacy policies and procedures; and\nb. Notify <personnel or roles> within <time period> when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction.","supplemental_guidance":"Organizational sanctions reflect applicable laws, executive orders, directives, regulations, policies, standards, and guidelines. Sanctions processes are described in access agreements and can be included as part of general personnel policies for organizations and/or specified in security and privacy policies. Organizations consult with the Office of the General Counsel regarding matters of employee sanctions.","implementation_level":"organization","parameters":[{"id":"ps-08_odp.01","label":"personnel or roles"},{"id":"ps-08_odp.02","label":"time period"}],"objectives":[{"id":"ps-8_obj.a","label":"PS-08a.","text":"a formal sanctions process is employed for individuals failing to comply with established information security and privacy policies and procedures;"},{"id":"ps-8_obj.b","label":"PS-08b.","text":"{{ insert: param, ps-08_odp.01 }} is/are notified within {{ insert: param, ps-08_odp.02 }} when a formal employee sanctions process is initiated, identifying the individual sanctioned and the reason for the sanction."}],"methods":[{"method":"examine","label":"PS-08-Examine"},{"method":"interview","label":"PS-08-Interview"},{"method":"test","label":"PS-08-Test"}],"related_controls":["PL-4","PM-12","PS-6","PT-1"]},{"id":"PS-9","oscal_id":"ps-9","family":"PS","title":"Position Descriptions","statement":"Incorporate security and privacy roles and responsibilities into organizational position descriptions.","supplemental_guidance":"Specification of security and privacy roles in individual organizational position descriptions facilitates clarity in understanding the security or privacy responsibilities associated with the roles and the role-based security and privacy training requirements for the roles.","implementation_level":"organization","objectives":[{"id":"ps-9_obj-1","label":"PS-09[01]","text":"security roles and responsibilities are incorporated into organizational position descriptions;"},{"id":"ps-9_obj-2","label":"PS-09[02]","text":"privacy roles and responsibilities are incorporated into organizational position descriptions."}],"methods":[{"method":"examine","label":"PS-09-Examine"},{"method":"interview","label":"PS-09-Interview"},{"method":"test","label":"PS-09-Test"}],"references":[{"title":"SP 800-181"}]}]};
